// Conversion offer logic: when a lead is detected, inject a discount offer to drive paid event
const axios = require('axios');
const { BACKEND_URL } = require('../constants/config');

async function applyConversionOffer(leadId, leadData) {
  // If lead has high intent (e.g., visited pricing page), offer a discount
  if (leadData.intentScore > 0.7) {
    try {
      await axios.post(`${BACKEND_URL}/api/offer`, {
        leadId,
        offer: { type: 'discount', value: 20, expiresIn: 3600 },
        source: 'conversion-offer'
      });
      return { applied: true, offerValue: 20 };
    } catch (err) {
      console.error('Conversion offer failed:', err.message);
      return { applied: false, error: err.message };
    }
  }
  return { applied: false, reason: 'low_intent' };
}

module.exports = { applyConversionOffer };
